css:
/* @prim:begin 43-action-menu */
.amenu{position:relative;display:inline-block}
.amenu-btn{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:0 10px;border:0;border-radius:var(--ds-r-sm);background:none;color:var(--cyan);font:inherit;font-weight:600;cursor:pointer}
.amenu-btn svg{width:.75rem;height:.75rem;flex:none;transition:transform var(--dur-fast) var(--ease-out)}
.amenu-btn[aria-expanded="true"] svg{transform:rotate(180deg)}
.amenu-btn:hover{background:var(--cyan-bg)}
.amenu-btn:focus-visible{outline:2px solid var(--cyan);outline-offset:-2px}
.amenu-list{position:absolute;right:0;top:calc(100% + 6px);z-index:40;min-width:17rem;padding:6px;background:var(--surface);border:1px solid var(--border);border-radius:var(--ds-r-sm);box-shadow:0 4px 12px rgba(0,0,0,.12)}
.amenu-i,.amenu-cta{display:flex;align-items:center;gap:10px;min-height:44px;padding:0 10px;border-radius:var(--ds-r-sm);color:var(--text);text-decoration:none;font-weight:500}
.amenu-i svg,.amenu-cta svg{width:1rem;height:1rem;flex:none;order:2;margin-left:auto}
.amenu-i svg{color:var(--cyan)}
.amenu-i:hover{background:var(--surface-2)}
.amenu-i:focus-visible,.amenu-cta:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}
.amenu-cta{margin-top:6px;background:var(--cyan);color:var(--surface);font-weight:600}
.amenu-cta:hover{filter:brightness(1.08)}
.amenu-group{padding:2px 0 8px}
.amenu-h{margin:8px 10px 2px;font-size:var(--fs-label);font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text-secondary)}
@media (prefers-reduced-motion:reduce){.amenu-btn svg{transition:none}}
/* @prim:end 43-action-menu */

