var KI={dl:'<path d="M8 2.5v7.5M4.75 7 8 10.25 11.25 7M3 13.5h10"/>',ext:'<path d="M9 2.5h4.5V7M13.5 2.5 7.5 8.5M11.5 9.5v3a1 1 0 01-1 1h-7a1 1 0 01-1-1v-7a1 1 0 011-1h3"/>',cal:'<rect x="2.5" y="3.5" width="11" height="10" rx="1.5"/><path d="M2.5 6.5h11M5.5 2v3M10.5 2v3"/>',chev:'<path d="M4.5 6.5 8 10l3.5-3.5"/>',right:'<path d="M6 3.5 10.5 8 6 12.5"/>',x:'<path d="M4 4l8 8M12 4l-8 8"/>'};
function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var AM={label:'Agreement',items:[{text:'PDF, for print',href:'#pdf',kind:'download',aria:'PDF, for print: download the agreement'},{text:'Word, for counsel',href:'#docx',kind:'download',aria:'Word, for counsel: download the agreement to edit'},{text:'Google Doc, for comments',href:'#doc',kind:'external',aria:'Google Doc, for comments (opens in a new tab)'}],cta:{text:'Discuss',href:'#call'}};
function amItems(d){return d.items.map(function(it){var x=it.kind==='external';return '<a class="amenu-i" href="'+kEsc(it.href)+'"'+(x?' target="_blank" rel="noopener"':' download')+' aria-label="'+kEsc(it.aria||it.text)+'"><span>'+kEsc(it.text)+'</span>'+kIcon(x?'ext':'dl')+'</a>';}).join('')+(d.cta?'<a class="amenu-cta" href="'+kEsc(d.cta.href)+'" target="_blank" rel="noopener" aria-label="'+kEsc(d.cta.text)+' (opens in a new tab)"><span>'+kEsc(d.cta.text)+'</span>'+kIcon('cal')+'</a>':'');}
function kitActionMenu(host,d,id,open){var w=document.createElement('div');w.className='amenu';w.innerHTML='<button type="button" class="amenu-btn" aria-expanded="false" aria-controls="'+id+'"><span>'+kEsc(d.label)+'</span>'+kIcon('chev')+'</button><div id="'+id+'" class="amenu-list" hidden>'+amItems(d)+'</div>';host.appendChild(w);
var b=w.querySelector('.amenu-btn'),m=w.querySelector('.amenu-list');function set(o,f){m.hidden=!o;b.setAttribute('aria-expanded',String(o));if(o&&f){var a=m.querySelector('a');if(a)a.focus();}if(!o&&f)b.focus();}
b.addEventListener('click',function(){set(m.hidden,true);});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!m.hidden){set(false,true);}});document.addEventListener('click',function(e){if(!w.contains(e.target))set(false);});if(open)set(true);return w;}
function kitActionGroup(host,d){var g=document.createElement('div');g.className='amenu-group';g.setAttribute('role','group');g.setAttribute('aria-label',d.label);g.innerHTML='<p class="amenu-h" aria-hidden="true">'+kEsc(d.label)+'</p>'+amItems(d);host.appendChild(g);return g;}
var st=kSlot();st.style.display='flex';st.style.justifyContent='flex-end';st.style.alignItems='flex-start';st.style.minHeight='16rem';kitActionMenu(st,AM,'am-stage');
STATES.forEach(function(s,i){var el=kSlot(i);if(s[0]==='phone'){kitActionGroup(el,AM);return;}el.style.display='flex';el.style.justifyContent='flex-end';el.style.alignItems='flex-start';if(s[0]==='open')el.style.minHeight='15rem';var w=kitActionMenu(el,AM,'am-s'+i,false);if(s[0]==='open'){var m=w.querySelector('.amenu-list');m.hidden=false;w.querySelector('.amenu-btn').setAttribute('aria-expanded','true');}});
